#!/system/bin/sh
main_func(){ F="$@"; U="${0%/*}/bin/busybox"; base="${F##*/}"; dir="${F%$base}"; [ -n "$dir" ] || dir="./"; name="${base%.*}"; OUT="${dir}${name}_MSAPatcher_DirectRisk.txt"; L="$($U unzip -qql "$F" 2>/dev/null | $U sed 's|.* ||g')"; dex=$(echo "$L"|$U grep -E '^classes([0-9]*)?\.dex$'|$U wc -l|$U tr -d ' '); so=$(echo "$L"|$U grep -E '^lib/.+\.so$'|$U wc -l|$U tr -d ' '); risk=0; [ "$dex" -gt 1 ] && risk=$((risk+1)); [ "$so" -gt 0 ] && risk=$((risk+1));
blobscan(){ p="$1"; n=0; for d in $(echo "$L"|$U grep -E '^classes([0-9]*)?\.dex$'); do x="$($U unzip -p "$F" "$d" 2>/dev/null|$U grep -a -E -o "$p" 2>/dev/null|$U head -n 20|$U wc -l|$U tr -d ' ')"; n=$((n+x)); done; echo "$n"; }
refl=$(blobscan 'DexClassLoader|PathClassLoader|Class\.forName|java/lang/reflect'); web=$(blobscan 'addJavascriptInterface|WebView|evaluateJavascript'); integ=$(blobscan 'getPackageInfo|SigningInfo|GET_SIGNATURES|signatures|certificate|integrity|tamper'); pack=$(echo "$L"|$U grep -E -i 'jiagu|bangcle|secexe|libshell|protect|packer'|$U wc -l|$U tr -d ' '); [ "$refl" -gt 0 ] && risk=$((risk+1)); [ "$integ" -gt 0 ] && risk=$((risk+1)); [ "$pack" -gt 0 ] && risk=$((risk+2)); level=LOW; [ "$risk" -ge 2 ] && level=MEDIUM; [ "$risk" -ge 4 ] && level=HIGH;
{ echo "MSAPatcher 6.1 - Direct APK Risk Check"; echo "APK: $base"; echo; echo "Risk: $level (score $risk)"; echo "DEX count: $dex"; echo "Native libraries: $so"; echo "Dynamic loading/reflection markers: $refl"; echo "WebView/Javascript markers: $web"; echo "Signature/integrity markers: $integ"; echo "Packer/protection filename markers: $pack"; echo; echo "HIGH means direct modification is more likely to break the app; use source-level changes when available."; } > "$OUT"; setspan_green "\n  Direct risk check complete: $level"; setspan_blue "  Report: $OUT\n"; cat "$OUT"; }
[ -f "${0%/*}/bin/utils" ] && . "${0%/*}/bin/utils" || { setspan_red(){ echo "$@"; }; setspan_green(){ echo "$@"; }; setspan_blue(){ echo "$@"; }; }
ab_ort(){ setspan_red "\n  $*\n"; exit 1; }; [ -f "$@" ] || ab_ort "Select an APK file."; main_func "$@"; exit
